import type { Vehicle } from './vehicle-types'

/**
 * ~12 realistic Austin, TX BHPH lot vehicles, hand-written so `npm run dev`
 * renders a complete, populated site with zero infrastructure -- no
 * database, no live Frazer feed.
 *
 * Photos are generated by scripts/make-demo-photos.mjs into public/demo/.
 * Run `node scripts/make-demo-photos.mjs` after editing the vehicle list
 * below so the photo set stays in sync (slugs and filenames must match).
 *
 * This module is DEMO DATA ONLY. It is read by src/lib/inventory.ts when
 * `process.env.DEMO_MODE === 'true'`. Delete this file and the DEMO_MODE
 * branch in inventory.ts once the real Frazer feed is live.
 */

function photos(slug: string, year: number, make: string, model: string): Vehicle['photos'] {
  return [0, 1, 2].map((position) => ({
    id: `${slug}-photo-${position}`,
    position,
    urlThumb: `/demo/${slug}-${position}.jpg`,
    urlCard: `/demo/${slug}-${position}.jpg`,
    urlFull: `/demo/${slug}-${position}.jpg`,
    width: 1600,
    height: 1200,
    alt: `${year} ${make} ${model} — photo ${position + 1}`,
  }))
}

